43	function applyEdits(original: string, edits: EditOp[]): string {
44		let result = original;
45		for (const op of edits) {
46			const idx = result.indexOf(op.oldText);
47			if (idx === -1) continue; // unlocatable; the edit tool itself would error
48			result = result.slice(0, idx) + op.newText + result.slice(idx + op.oldText.length);
